def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Locate the colored horizontal bars on the top and bottom edges.
    def runs_on_edge(row):
        runs = []
        c = 0
        while c < w:
            if row[c] == row[0] and row[c] != grid[1][0]:
                # Not used: background may not be at row[0].
                pass
            c += 1

    # Background is the most frequent color.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def find_runs(r):
        runs = []
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            color = grid[r][c]
            start = c
            while c < w and grid[r][c] == color:
                c += 1
            if c - start >= 2:
                runs.append((start, c, color))
        return runs

    top_runs = find_runs(0)
    bottom_runs = find_runs(h - 1)
    if not top_runs or not bottom_runs:
        return out

    top = top_runs[0]
    bottom = bottom_runs[0]
    shift = bottom[0] - top[0]

    # All non-background cells other than the edge bars are marker(s).
    markers = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                is_bar = ((r == 0 and top[0] <= c < top[1] and grid[r][c] == top[2]) or
                          (r == h - 1 and bottom[0] <= c < bottom[1] and grid[r][c] == bottom[2]))
                if not is_bar:
                    markers.append((r, c, grid[r][c]))

    for r, c, color in markers:
        out[r][c] = 4
        # Extend the marker's column toward the top bar.
        for rr in range(1, r):
            if grid[rr][c] == bg:
                out[rr][c] = color

        # Its translated column extends toward the bottom bar.
        cc = c + shift
        if 0 <= cc < w:
            for rr in range(0, h - 1):
                if grid[rr][cc] == bg:
                    out[rr][cc] = color

    return out
